package com.tsk.carmedia
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.DisplayManager;import android.media.*;import android.media.projection.*;import android.os.*;import androidx.core.app.NotificationCompat;import java.io.ByteArrayOutputStream;import java.net.*;import java.nio.ByteBuffer;import java.util.concurrent.Executors;import java.util.concurrent.atomic.*
class MirrorService:Service(){var mp:MediaProjection?=null;var rd:ImageReader?=null;var vd:android.hardware.display.VirtualDisplay?=null;val ex=Executors.newSingleThreadExecutor();val busy=AtomicBoolean(false);val latest=AtomicReference<ByteArray?>(null);var ip="";var seq=0;var last=0L;var sent=0L
override fun onBind(i:Intent?)=null
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{val nm=getSystemService(NOTIFICATION_SERVICE) as NotificationManager;nm.createNotificationChannel(NotificationChannel("cm","Car Media",NotificationManager.IMPORTANCE_LOW));startForeground(1,note("UDP mirror active"));ip=i!!.getStringExtra("ip")!!;@Suppress("DEPRECATION") val data=i.getParcelableExtra<Intent>("data")!!;mp=(getSystemService(MEDIA_PROJECTION_SERVICE) as MediaProjectionManager).getMediaProjection(i.getIntExtra("code",0),data);mp!!.registerCallback(object:MediaProjection.Callback(){override fun onStop(){stopSelf()}},Handler(Looper.getMainLooper()));rd=ImageReader.newInstance(1280,480,PixelFormat.RGBA_8888,2);vd=mp!!.createVirtualDisplay("CarMedia",1280,480,240,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,rd!!.surface,null,null);rd!!.setOnImageAvailableListener({r->val now=System.nanoTime();val im=r.acquireLatestImage()?:return@setOnImageAvailableListener;if(now-last<40_000_000L){im.close();return@setOnImageAvailableListener};last=now;try{val p=im.planes[0];val pad=p.rowStride-p.pixelStride*im.width;val w=Bitmap.createBitmap(im.width+pad/p.pixelStride,im.height,Bitmap.Config.ARGB_8888);w.copyPixelsFromBuffer(p.buffer);val b=Bitmap.createBitmap(w,0,0,im.width,im.height);w.recycle();val o=ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,50,o);b.recycle();latest.set(o.toByteArray());pump()}finally{im.close()}},Handler(Looper.getMainLooper()));return START_NOT_STICKY}
fun pump(){if(!busy.compareAndSet(false,true))return;ex.execute{val s=DatagramSocket();try{while(true){val j=latest.getAndSet(null)?:break;seq++;val chunk=58000;val total=(j.size+chunk-1)/chunk;for(n in 0 until total){val a=n*chunk;val z=minOf(j.size,a+chunk);val h=ByteBuffer.allocate(16).putInt(0x434D3135).putInt(seq).putInt(n).putInt(total).array();val out=ByteArray(16+z-a);System.arraycopy(h,0,out,0,16);System.arraycopy(j,a,out,16,z-a);s.send(DatagramPacket(out,out.size,InetAddress.getByName(ip),8766))};sent++}}finally{s.close();busy.set(false);if(latest.get()!=null)pump();(getSystemService(NOTIFICATION_SERVICE) as NotificationManager).notify(1,note("Frames sent: $sent"))}}}
fun note(x:String)=NotificationCompat.Builder(this,"cm").setContentTitle("TSK Car Media v1.8.1.1 Pi Edition").setContentText(x).setSmallIcon(android.R.drawable.ic_media_play).setOnlyAlertOnce(true).build()
override fun onDestroy(){rd?.close();vd?.release();mp?.stop();ex.shutdownNow();super.onDestroy()}}